'use strict';
const token=document.querySelector('meta[name="techzone-token"]').content, content=document.querySelector('#content'), notice=document.querySelector('#notice'), dialog=document.querySelector('#dialog'), dc=document.querySelector('#dialog-content');
const descriptions={dashboard:'Tổng quan hoạt động và những việc cần theo dõi.',catalog:'Khám phá sản phẩm phù hợp với nhu cầu của bạn.',cart:'Kiểm tra sản phẩm và thông tin thanh toán.',orders:'Theo dõi đơn hàng và hành trình giao hàng.',inventory:'Theo dõi tồn kho và các đề nghị nhập hàng.',warranty:'Tra cứu bảo hành và yêu cầu hỗ trợ.',compatibility:'Theo dõi các cặp sản phẩm cần rà soát.',reports:'Theo dõi doanh số và dữ liệu kinh doanh.',admin:'Quản lý danh mục, AI và hoạt động hệ thống.',account:'Quản lý tài khoản và lựa chọn quyền riêng tư.'};
const titles={dashboard:'Tổng quan',catalog:'Tìm sản phẩm',cart:'Giỏ hàng & thanh toán',orders:'Đơn hàng & giao hàng',inventory:'Kho & nhập hàng',warranty:'Bảo hành & RMA',reports:'Báo cáo kinh doanh',account:'Tài khoản',compatibility:'Rà soát tương thích',admin:'Quản trị hệ thống'};
let state={},products=[],page=titles[location.hash.slice(1)]?location.hash.slice(1):'catalog',results=null,query='',recording=null,filters={category:'',socket:'',memory:'',maxPrice:'',specKey:'',specValue:''},comparison=new Set(),orderFilter='ALL',searchSequence=0;
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(x||0);
async function api(path,options={}){const headers=new Headers(options.headers||{});headers.set('X-TechZone-Token',token);const r=await fetch(path,{...options,headers});if(!r.ok)throw Error(await r.text());return r}
let marketOffers=new Map();
async function loadMarketOffers(){try{const data=await api('/v1/web/market-offers').then(r=>r.json());marketOffers=new Map(data.map(x=>[x.productId,x]))}catch(error){marketOffers=new Map()}}
function marketOffer(p){const o=marketOffers.get(p.id);if(!o || !/^https:\/\/gearvn\.com\/products\/[a-z0-9-]+$/.test(o.url))return '';const date=new Date(o.fetchedAt);const stale=!Number.isFinite(date.getTime())||Date.now()-date.getTime()>24*60*60*1000;const status=o.availability==='IN_STOCK'?'đang bán':o.availability==='OUT_OF_STOCK'?'hết hàng':'chưa rõ tình trạng';return `<div class="subtle">GearVN: <strong>${money(o.price)}</strong> · ${status}<br>${stale?'Dữ liệu quá 24 giờ · ':''}Cập nhật ${h(date.toLocaleString('vi-VN'))} · <a href="${h(o.url)}" target="_blank" rel="noopener noreferrer">Xem nguồn ↗</a></div>`}
let noticeTimer;
function msg(text,error=false){clearTimeout(noticeTimer);notice.replaceChildren(document.createTextNode(text));const close=document.createElement('button');close.type='button';close.className='notice-close';close.setAttribute('aria-label','Đóng thông báo');close.textContent='×';close.addEventListener('click',()=>{notice.hidden=true});notice.append(close);notice.hidden=false;notice.className=error?'error':'';notice.setAttribute('role',error?'alert':'status');if(!error&&!text.startsWith('Đang '))noticeTimer=setTimeout(()=>{notice.hidden=true},5000);}
async function refresh(){await loadMarketOffers();[state,products]=await Promise.all([api('/v1/web/state').then(r=>r.json()),api('/v1/products').then(r=>r.json()).then(items=>items.filter(p=>p.active))]);const count=state.cart.reduce((a,b)=>a+b.quantity,0);document.querySelector('#cart-count').textContent=count||'';const badge=document.querySelector('.header-cart-count');badge.textContent=count;badge.hidden=!count}
let aiStatusPending=false;
async function refreshAiStatus(){
  if(page!=='admin'||adminTab!=='ai'||document.hidden||aiStatusPending)return;
  aiStatusPending=true;
  try{
    const status=await api('/v1/web/ai-status').then(r=>r.json());
    state.searchModel=status.searchModel;
    const label=document.querySelector('[data-search-model]');
    if(page==='admin'&&adminTab==='ai'&&label)label.textContent=status.searchModel;
  }catch(error){
    const label=document.querySelector('[data-search-model]');
    if(page==='admin'&&adminTab==='ai'&&label)label.textContent='Không kết nối được backend';
  }finally{aiStatusPending=false}
}
setInterval(refreshAiStatus,5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAiStatus()});
async function track(data){await api('/v1/web/action',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)})}
let actionPending=false;
async function action(data){if(actionPending){msg('Thao tác trước đang được xử lý, vui lòng chờ.');return}const checkoutForm=document.querySelector('#checkout');const savedCheckout=data.action==='quantity'&&checkoutForm?Object.fromEntries(new FormData(checkoutForm)):null;actionPending=true;try{msg('Đang xử lý…');const body=new URLSearchParams(data);const r=await api('/v1/web/action',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const out=await r.json();await refresh();render();if(savedCheckout){const form=document.querySelector('#checkout');for(const [key,value] of Object.entries(savedCheckout))if(form.elements[key])form.elements[key].value=value;updateTotals()}msg(out.message)}finally{actionPending=false}}
function productCard(p,primary=''){
  return `<article class="product"><div class="product-image"><span class="product-stock ${p.available?'':'out'}">${p.available?'● Còn hàng':'Hết hàng'}</span><img src="/v1/products/${encodeURIComponent(p.id)}/image?token=${encodeURIComponent(token)}" alt="${h(p.name)}" loading="lazy"></div><div class="product-body"><div class="product-brand">${h(p.brand)} <span> / ${h(p.sku)}</span></div><h3>${h(p.name)}</h3><div class="product-warranty">${p.warrantyMonths > 0 ? 'Bảo hành '+p.warrantyMonths+' tháng <span>·</span> ' : ''}Tồn kho ${p.available}</div><div class="price">${money(p.effectivePrice)}</div>${marketOffer(p)}<div class="product-bottom"><label class="compare-check"><input type="checkbox" data-compare="${h(p.id)}" ${comparison.has(p.id)?'checked':''}> So sánh</label><div class="product-actions"><button class="secondary" data-detail="${h(p.id)}">Chi tiết</button><button data-add="${h(p.id)}" data-primary="${h(primary)}" ${p.available?'':'disabled'}>Thêm vào giỏ</button></div></div></div></article>`
}
function recommendationCards(recs,primary){
  return recs.items.map(x=>`<div class="recommendation-item">${productCard(x.product,primary)}<p class="compatibility-note">${h(x.compatibility)}</p></div>`).join('');
}
async function compareProducts(){
  const selected=products.filter(p=>comparison.has(p.id));
  if(selected.length<2||selected.length>8){msg('Hãy chọn từ 2 đến 8 sản phẩm để so sánh.',true);return}
  const result=await api('/v1/web/compare-check?ids='+encodeURIComponent(selected.map(p=>p.id).join(','))).then(r=>r.json());
  const pairRows=result.pairs.map(x=>`<li><strong>${h(x.left)} / ${h(x.right)}:</strong> ${x.status==='CONFLICT'?'Xung đột hoặc bị chặn':x.approved?'Cặp đã duyệt':'Chưa được duyệt'} · ${h(x.detail)}</li>`).join('');
  const physicalRows=result.physical.map(x=>`<li><strong>${h(x.name)}:</strong> ${x.status==='pass'?'Đạt điều kiện đã kiểm tra':x.status==='fail'?'Không đạt':'Chưa xác minh'} · ${h(x.detail)}</li>`).join('');
  open(`<h2>So sánh sản phẩm</h2><div class="table-wrap"><table><thead><tr><th>Thông tin</th>${selected.map(p=>`<th>${h(p.name)}</th>`).join('')}</tr></thead><tbody><tr><td>Giá hiện tại</td>${selected.map(p=>`<td>${money(p.effectivePrice)}</td>`).join('')}</tr><tr><td>Tồn kho hiện tại</td>${selected.map(p=>`<td>${p.available}</td>`).join('')}</tr>${[...new Set(selected.flatMap(p=>Object.keys(p.specs)))].map(k=>`<tr><td>${h(k)}</td>${selected.map(p=>`<td>${h(p.specs[k]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><section class="detail-section"><h3>Đối chiếu tương thích</h3><p class="subtle">Kết quả chỉ bao gồm các điều kiện có dữ liệu; hãy kiểm tra các mục chưa xác minh trước khi mua thực tế.</p><ul>${pairRows+physicalRows||'<li>Chưa có quy tắc đối chiếu cho các sản phẩm đã chọn.</li>'}</ul></section>`);
}
function retrySemanticRecommendations(primary,current,valid,onUpdate){
  if(!current.items.length || /BGE-M3|MiniLM/.test(current.strategy))return;
  let attempts=0;
  const retry=async()=>{
    if(!valid() || attempts++>=10)return;
    try{
      const status=await api('/v1/web/ai-status').then(r=>r.json());
      if(!valid())return;
      if(!['BGE-M3','MiniLM'].includes(status.searchModel)){
        if(status.searchModel.includes('khởi động'))setTimeout(retry,3000);
        return;
      }
      const updated=await api('/v1/products/'+encodeURIComponent(primary)+'/recommendations').then(r=>r.json());
      if(!valid())return;
      if(updated.items.length && /BGE-M3|MiniLM/.test(updated.strategy)){onUpdate(updated);return}
      setTimeout(retry,2500);
    }catch(error){/* Optional refinement never blocks shopping. */}
  };
  setTimeout(retry,2000);
}
function enhance(root){
  root.querySelectorAll('button:not(nav button)').forEach(b=>b.classList.add('btn',b.classList.contains('secondary')?'btn-subtle':'btn-solid'));
  root.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"]),select,textarea').forEach(el=>el.classList.add('form-control'));
  root.querySelectorAll('.panel,.product,.metric').forEach(el=>el.classList.add('card'));
  root.querySelectorAll('table').forEach(el=>el.classList.add('table'));
}
function render(){document.querySelectorAll('nav button').forEach(b=>b.hidden=!allowed(b.dataset.page));if(!allowed(page))page='dashboard';document.querySelector('#title').textContent=titles[page];document.querySelector('.header-description').textContent=descriptions[page];document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.querySelector('.header-cart').hidden=!allowed('cart');if(page==='dashboard')dashboard();if(page==='catalog')catalog();if(page==='cart'){cart();updateTotals()}if(page==='orders')orders();if(page==='inventory')inventory();if(page==='warranty')warranty();if(page==='reports')reports();if(page==='account')account();if(page==='compatibility')compatibility();if(page==='admin')admin();enhance(content);if(page==='admin')refreshAiStatus();if(page==='cart'){loadCartRecommendations();loadBuildChecks()}}
function catalog(){
  let list=results===null?products:results.map(id=>products.find(p=>p.id===id)).filter(Boolean);
  const categories=[...new Set(products.map(p=>p.category))];
  content.innerHTML=`<section class="catalog-hero"><div class="hero-copy"><div class="hero-kicker"><span class="sparkle">✦</span> KHÁM PHÁ CÔNG NGHỆ</div><h2>Tìm đúng sản phẩm<br><span>cho nhu cầu của bạn.</span></h2><p>Tìm kiếm thông minh theo mô tả, hình ảnh hoặc giọng nói. Chọn sản phẩm phù hợp thật dễ dàng.</p><div class="hero-details"><span>✦ Tìm kiếm AI</span><span>✓ Gợi ý tương thích</span><span>◇ Bảo hành điện tử</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-card"><span>TECHZONE</span><strong>SMART<br>CHOICE<span>.</span></strong><small>Khám phá sản phẩm phù hợp</small></div><span class="art-spark art-spark-one">✳</span><span class="art-spark art-spark-two">✦</span></div></section>
  <section class="panel search-panel"><div class="search-heading"><div><span class="section-kicker">TÌM KIẾM THÔNG MINH</span><h2>Tìm đúng sản phẩm bạn cần</h2><p class="muted">Nhập nhu cầu hoặc tải lên ảnh sản phẩm để bắt đầu.</p></div><span class="search-badge">✦ &nbsp; AI SEARCH</span></div><form id="search" class="toolbar search-bar"><div class="search-field"><span aria-hidden="true">⌕</span><input name="query" value="${h(query)}" placeholder="Ví dụ: CPU chơi game, RAM DDR5..." aria-label="Nội dung tìm kiếm"></div><button>Tìm kiếm <span aria-hidden="true">→</span></button><button type="button" class="secondary" id="voice">🎙 Giọng nói</button><label class="secondary file-button">▧ Chọn ảnh<input id="image" type="file" accept="image/*,.heic,.heif" hidden></label></form><details class="advanced-filters" ${Object.values(filters).some(Boolean)?'open':''}><summary><span>⚑ &nbsp; Bộ lọc chi tiết</span><span class="filter-chevron" aria-hidden="true">⌄</span></summary><div class="toolbar filter-grid"><label>Danh mục<select form="search" name="category"><option value="">Tất cả</option>${categories.map(c=>`<option value="${h(c)}" ${filters.category===c?'selected':''}>${h(c)}</option>`).join('')}</select></label><label>Socket<input form="search" name="socket" value="${h(filters.socket)}" placeholder="VD: AM5"></label><label>Bộ nhớ<input form="search" name="memory" value="${h(filters.memory)}" placeholder="VD: DDR5"></label><label>Giá tối đa<input form="search" name="maxPrice" type="number" min="0" value="${h(filters.maxPrice)}" placeholder="VNĐ"></label><label>Tên thông số<input form="search" name="specKey" value="${h(filters.specKey)}" placeholder="Ví dụ: chipset"></label><label>Giá trị<input form="search" name="specValue" value="${h(filters.specValue)}"></label></div></details><p class="subtle search-hint" id="search-hint">Lần đầu dùng AI có thể mất một chút thời gian khởi tạo.</p></section>
  <section class="catalog-results"><div class="results-heading"><div><span class="section-kicker">DANH MỤC TECHZONE</span><h2>Sản phẩm <span class="results-count">${list.length}</span></h2><p class="muted">Khám phá các sản phẩm phù hợp với bạn.</p></div><button class="secondary" id="refresh-gearvn">↻ Cập nhật giá GearVN</button><button class="secondary compare-button" id="compare">⇄ &nbsp; So sánh (${comparison.size})</button></div><div class="category-chips" aria-label="Lọc theo danh mục"><button aria-pressed="${!filters.category}" class="category-chip ${!filters.category?'selected':''}" type="button" data-category="">Tất cả</button>${categories.map(c=>`<button aria-pressed="${filters.category===c}" class="category-chip ${filters.category===c?'selected':''}" type="button" data-category="${h(c)}">${h(c)}</button>`).join('')}</div><div class="grid product-grid">${list.map(p=>productCard(p)).join('')||'<div class="empty-results"><span>⌕</span><h3>Chưa tìm thấy sản phẩm</h3><p>Thử từ khóa khác hoặc điều chỉnh bộ lọc để xem thêm kết quả.</p></div>'}</div></section>`
}
function cart(){
  const quantity=state.cart.reduce((n,i)=>n+i.quantity,0);
  content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">GIỎ HÀNG CỦA BẠN</span><h2>Sẵn sàng cho lựa chọn tiếp theo?</h2><p>Kiểm tra sản phẩm trước khi hoàn tất đơn hàng.</p></div><div class="intro-icon" aria-hidden="true">▣</div></div><div class="checkout-layout"><section class="panel cart-panel"><div class="panel-title-row"><div><span class="section-kicker">SẢN PHẨM ĐÃ CHỌN</span><h2>Giỏ hàng <span class="results-count">${quantity}</span></h2></div><button class="secondary text-button" data-page="catalog">← Tiếp tục mua sắm</button></div>${state.cart.length?`<div class="cart-items">${state.cart.map(i=>{const p=products.find(x=>x.id===i.id);return `<div class="cart-item"><div class="cart-thumb"><img src="/v1/products/${encodeURIComponent(i.id)}/image?token=${encodeURIComponent(token)}" alt="${h(i.name)}"></div><div class="cart-info"><span class="product-brand">${h(p?.brand||'TECHZONE')}</span><h3>${h(i.name)}</h3><span class="subtle">${money(i.price)} / sản phẩm</span></div><div class="cart-controls"><strong>${money(i.price*i.quantity)}</strong><div class="quantity-control"><button class="secondary" data-qty="${h(i.id)}" data-n="${i.quantity-1}" aria-label="Giảm số lượng ${h(i.name)}">−</button><span aria-label="Số lượng">${i.quantity}</span><button class="secondary" data-qty="${h(i.id)}" data-n="${i.quantity+1}" aria-label="Tăng số lượng ${h(i.name)}">+</button></div></div></div>`}).join('')}</div><div class="cart-validation ${(state.cartValidation||state.cartCompatibilityWarning)?'warning':''}"><span>${state.cartValidation||state.cartCompatibilityWarning?'!':'✓'}</span>${h(state.cartValidation||state.cartCompatibilityWarning||'Có thể tiếp tục thanh toán.')}</div><div id="cart-build-checks" aria-live="polite"></div><div id="cart-recommendations"></div>`:`<div class="cart-empty"><span class="empty-illustration">▣</span><h3>Giỏ hàng của bạn đang trống</h3><p>Khám phá sản phẩm và thêm những món phù hợp với bạn.</p><button data-page="catalog">Khám phá sản phẩm →</button></div>`}</section><section class="panel checkout-panel"><span class="section-kicker">TÓM TẮT ĐƠN HÀNG</span><h2>Thông tin thanh toán</h2><p class="checkout-hint">Kiểm tra thông tin trước khi tạo đơn.</p><form id="checkout" class="stack"><label>Địa chỉ giao hàng<input name="address" required value="${h(state.address)}" placeholder="Nhập địa chỉ nhận hàng"></label><label>Mã ưu đãi<input name="promotion" placeholder="TECHZONE5 hoặc WELCOME500"></label><label>Phương thức thanh toán<select name="payment"><option>Ví điện tử</option><option>Thẻ nội địa / QR</option><option>Chuyển khoản ngân hàng</option></select></label><label>Kết quả thanh toán<select name="verdict"><option value="AUTHORIZED">Thành công</option><option value="DECLINED">Từ chối</option><option value="UNKNOWN">Chờ đối soát</option></select></label><div id="cart-totals" class="checkout-totals" aria-live="polite"></div><button class="checkout-button" ${state.cart.length?'':'disabled'}>Xác nhận đặt hàng <span>→</span></button><div class="checkout-safe"><span>◇</span> Chưa kết nối cổng thanh toán và đơn vị vận chuyển.</div></form></section></div>`
}
async function loadBuildChecks(){
  const holder=document.querySelector('#cart-build-checks');if(!holder)return;
  try{const checks=await api('/v1/web/build-check').then(r=>r.json());if(!holder.isConnected)return;
    if(!checks.length){holder.replaceChildren();return}
    holder.innerHTML=`<details class="detail-review"><summary>Kiểm tra vỏ máy, kích thước, cáp và BIOS</summary><ul>${checks.map(c=>`<li><strong>${c.status==='pass'?'Đạt điều kiện':c.status==='fail'?'Không đạt':'Chưa xác minh'} · ${h(c.name)}</strong>: ${h(c.detail)}</li>`).join('')}</ul></details>`;
  }catch(error){holder.textContent='Không kiểm tra được thông số cấu hình.'}
}
let cartRecommendationSequence=0;
async function loadCartRecommendations(){
  const holder=document.querySelector('#cart-recommendations');
  if(!holder||!state.cart.length)return;
  const sequence=++cartRecommendationSequence;
  const selected=holder.querySelector('select')?.value || state.cart[0].id;
  holder.innerHTML=`<div class="cart-recommendation-heading"><label for="cart-recommendation-primary">Gợi ý cho sản phẩm</label><select id="cart-recommendation-primary" class="form-control">${state.cart.map(item=>`<option value="${h(item.id)}" ${item.id===selected?'selected':''}>${h(item.name)}</option>`).join('')}</select></div><div class="cart-recommendation-results" aria-live="polite"><p class="subtle">Đang tìm sản phẩm tương thích…</p></div>`;
  const result=holder.querySelector('.cart-recommendation-results');
  try{
    const recs=await api('/v1/products/'+encodeURIComponent(selected)+'/recommendations').then(r=>r.json());
    if(sequence!==cartRecommendationSequence||!holder.isConnected||page!=='cart')return;
    track({action:'track_recs',id:selected,ids:recs.items.map(x=>x.product.id).join(','),strategy:recs.strategy}).catch(()=>{});
    if(!recs.items.length){result.innerHTML='<p class="subtle">Chưa tìm thấy sản phẩm để gợi ý theo dữ liệu hiện có.</p>';return}
    result.innerHTML=`<h3>Phù hợp với lựa chọn của bạn</h3><div class="grid detail-recommendations">${recommendationCards(recs,selected)}</div>`;
    enhance(result);
    retrySemanticRecommendations(selected,recs,()=>sequence===cartRecommendationSequence&&holder.isConnected&&page==='cart',updated=>{
      result.querySelector('.detail-recommendations').innerHTML=recommendationCards(updated,selected);enhance(result);
      track({action:'track_recs',id:selected,ids:updated.items.map(x=>x.product.id).join(','),strategy:updated.strategy}).catch(()=>{});
    });
  }catch(error){if(sequence===cartRecommendationSequence&&holder.isConnected&&page==='cart')result.innerHTML='<p class="subtle">Gợi ý tạm thời chưa sẵn sàng. Bạn vẫn có thể thanh toán.</p>'}
}
function updateTotals(){const node=document.querySelector('#cart-totals');if(!node)return;const promo=document.querySelector('#checkout [name=promotion]').value.trim().toUpperCase();const base=state.subtotal;const discount=promo==='TECHZONE5'?Math.min(Math.floor(base*state.promotionPercent/100),1000000):promo==='WELCOME500'&&base>=5000000?500000:0;const taxable=Math.max(0,base-discount),vat=Math.floor(taxable/10),shipping=taxable>=2000000||!base?0:35000;node.innerHTML=`<div><span>Tạm tính</span><strong>${money(base)}</strong></div><div><span>Ưu đãi</span><strong>${discount?'− ':''}${money(discount)}</strong></div><div><span>Thuế VAT</span><strong>${money(vat)}</strong></div><div><span>Giao hàng</span><strong>${shipping?money(shipping):'Miễn phí'}</strong></div><div class="checkout-total"><span>Tổng dự kiến</span><strong>${money(taxable+vat+shipping)}</strong></div>`}
function orders(){
  const all=state.orders.filter(o=>document.querySelector('#role').value!=='CUSTOMER'||o.customerId===state.customerId);
  const groups={ALL:all,ACTIVE:all.filter(o=>['PENDING_PAYMENT','PENDING_REVIEW','CONFIRMED','PACKED','SHIPPED'].includes(o.rawStatus)),DELIVERED:all.filter(o=>o.rawStatus==='DELIVERED'),CANCELLED:all.filter(o=>o.rawStatus==='CANCELLED')};
  const list=groups[orderFilter]||all;
  content.innerHTML=`<div class="page-intro orders-intro"><div><span class="section-kicker">THEO DÕI VẬN HÀNH</span><h2>Mọi đơn hàng, trong tầm tay.</h2><p>Theo dõi trạng thái, cấp phát Serial và cập nhật hành trình giao hàng.</p></div><div class="intro-icon" aria-hidden="true">☷</div></div><div class="order-filter" aria-label="Lọc đơn hàng">${[['ALL','Tất cả'],['ACTIVE','Đang xử lý'],['DELIVERED','Đã giao'],['CANCELLED','Đã hủy']].map(([key,label])=>`<button class="order-tab ${orderFilter===key?'selected':''}" data-order-filter="${key}" aria-pressed="${orderFilter===key}">${label}<span>${groups[key].length}</span></button>`).join('')}</div><div class="order-list">${list.map(o=>`<article class="panel order-card"><div class="order-card-head"><div class="order-ident"><div class="order-icon">▣</div><div><span class="subtle">MÃ ĐƠN HÀNG</span><h3>${h(o.number)}</h3><span class="subtle">${h(o.id)}</span></div></div><div class="order-top-right"><span class="order-status ${o.rawStatus==='DELIVERED'?'success':o.rawStatus==='CANCELLED'?'cancelled':'processing'}">● ${h(o.status)}</span><strong>${money(o.total)}</strong></div></div><div class="order-meta"><div><span>ĐỊA CHỈ NHẬN HÀNG</span><strong>${h(o.address)}</strong></div><div><span>VẬN ĐƠN</span><strong>${h(o.tracking||'Chưa có vận đơn')}</strong></div></div><div class="order-items">${o.lines.map(l=>{const p=products.find(x=>x.id===l.id);return `<div><span>${h(p?.name||l.id)} <small>× ${l.quantity}</small></span><span class="subtle">Đã cấp ${l.allocated}${l.serials?' · '+h(l.serials):''}</span></div>`}).join('')}</div><div class="order-footer"><details class="order-history"><summary>Hành trình & ghi chú <span>⌄</span></summary>${o.journey.map(e=>`<p>${h(e.time)} · ${h(e.milestone)} · ${h(e.location)}</p>`).join('')}${o.notes.map(n=>`<p>${h(n.author)}: ${h(n.note)}</p>`).join('')||(!o.journey.length?'<p>Chưa có cập nhật.</p>':'')}</details>${document.querySelector('#role').value==='CUSTOMER'?'':`<button class="secondary" data-order="${h(o.id)}">Xử lý đơn <span>→</span></button>`}</div></article>`).join('')||'<div class="empty-results"><span>☷</span><h3>Chưa có đơn hàng phù hợp</h3><p>Hãy chọn trạng thái khác để xem thêm đơn hàng.</p></div>'}</div>`
}
function inventory(){
  const pending=state.requests.filter(r=>r.status==='Chờ nhà cung cấp xác nhận').length;
  content.innerHTML=`<div class="page-intro operation-intro"><div><span class="section-kicker">VẬN HÀNH CỬA HÀNG</span><h2>Kho hàng trong tầm kiểm soát.</h2><p>Theo dõi tồn kho, kiểm kê và nhập hàng tại một nơi.</p></div><div class="intro-icon" aria-hidden="true">▤</div></div><div class="operation-metrics"><div class="operation-metric"><span class="op-icon blue">▤</span><div><span>SẢN PHẨM TRONG DANH MỤC</span><strong>${products.length}</strong><small>Mã sản phẩm đang theo dõi</small></div></div><div class="operation-metric"><span class="op-icon teal">✓</span><div><span>SẴN SÀNG ĐỂ BÁN</span><strong>${state.available}</strong><small>Đơn vị trong kho</small></div></div><div class="operation-metric"><span class="op-icon amber">↗</span><div><span>ĐỀ NGHỊ NHẬP HÀNG</span><strong>${pending}</strong><small>Đang chờ nhà cung cấp</small></div></div></div><section class="panel stock-panel"><div class="stock-heading"><div><span class="section-kicker">DANH SÁCH SẢN PHẨM</span><h2>Tồn kho <span class="results-count">${products.length}</span></h2><p>Theo dõi số lượng và thực hiện thao tác kho.</p></div><label class="stock-search"><span aria-hidden="true">⌕</span><input id="inventory-filter" type="search" placeholder="Tìm tên hoặc mã sản phẩm" aria-label="Tìm sản phẩm trong kho"></label></div><div class="table-wrap"><table class="stock-table"><thead><tr><th>SẢN PHẨM</th><th>SKU</th><th>CÓ THỂ BÁN</th><th>THAO TÁC</th></tr></thead><tbody>${products.map(p=>`<tr data-stock-row data-search="${h((p.name+' '+p.sku+' '+p.id).toLocaleLowerCase('vi'))}"><td><div class="stock-product"><div class="stock-thumb"><img src="/v1/products/${encodeURIComponent(p.id)}/image?token=${encodeURIComponent(token)}" alt=""></div><div><strong>${h(p.name)}</strong><small>${h(p.brand)}</small></div></div></td><td>${h(p.sku)}</td><td><span class="stock-amount ${p.available?'':'empty'}">● &nbsp; ${p.available} sản phẩm</span></td><td><button class="secondary" data-stock="${h(p.id)}">Xử lý <span>→</span></button></td></tr>`).join('')}</tbody></table><p class="stock-no-results" id="inventory-empty" hidden>Không tìm thấy sản phẩm phù hợp.</p></div></section><section class="panel restock-panel"><div class="panel-title-row"><div><span class="section-kicker">NHẬP HÀNG</span><h2>Đề nghị nhập hàng <span class="results-count">${state.requests.length}</span></h2></div></div>${state.requests.map(r=>`<div class="restock-row"><span class="op-icon blue">↗</span><div><strong>${h(r.id)} · ${h(r.product)}</strong><small>Số lượng ${r.quantity} · ${h(r.status)}</small></div><button class="secondary" data-receive="${h(r.id)}">Nhận hàng</button></div>`).join('')||'<div class="small-empty"><span>↗</span><p>Chưa có đề nghị nhập hàng.</p></div>'}</section>`
}
function warranty(){
  const isCustomer=document.querySelector('#role').value==='CUSTOMER';
  const warranties=state.warranties.filter(w=>!isCustomer||w.customerId===state.customerId);
  const rmas=state.rmas.filter(r=>!isCustomer||r.customerId===state.customerId);
  content.innerHTML=`<div class="page-intro warranty-intro"><div><span class="section-kicker">DỊCH VỤ & HỖ TRỢ</span><h2>Chăm sóc sản phẩm của bạn.</h2><p>Tra cứu bảo hành và theo dõi hỗ trợ kỹ thuật dễ dàng.</p></div><div class="intro-icon" aria-hidden="true">◇</div></div><div class="warranty-layout"><section class="panel warranty-list"><div class="stock-heading"><div><span class="section-kicker">BẢO HÀNH ĐIỆN TỬ</span><h2>Tra cứu bảo hành <span class="results-count">${warranties.length}</span></h2><p>Tìm thiết bị theo Serial hoặc mã sản phẩm.</p></div></div><label class="stock-search warranty-search"><span aria-hidden="true">⌕</span><input id="warranty-filter" type="search" placeholder="Nhập Serial hoặc mã sản phẩm" aria-label="Tra cứu bảo hành"></label><div class="warranty-items">${warranties.map(w=>`<div class="warranty-item" data-warranty-row data-search="${h((w.serial+' '+w.product).toLocaleLowerCase('vi'))}"><span class="warranty-icon">◇</span><div class="warranty-info"><strong>${h(w.serial)}</strong><small>${h(w.product)} · Hết hạn ${h(w.expires.slice(0,10))}</small></div><div class="warranty-actions"><span class="warranty-status ${w.status==='ACTIVE'?'':'inactive'}">${w.status==='ACTIVE'?'Còn hiệu lực':'Hết hạn'}</span><button class="secondary" data-use-serial="${h(w.serial)}" data-kind="${w.status==='ACTIVE'?'rma':'repair'}">Yêu cầu hỗ trợ</button></div></div>`).join('')||'<div class="small-empty"><span>◇</span><p>Chưa có bảo hành.</p></div>'}<p class="stock-no-results" id="warranty-empty" hidden>Không tìm thấy bảo hành phù hợp.</p></div></section><section class="panel support-form"><span class="section-kicker">CHÚNG TÔI CÓ THỂ GIÚP GÌ?</span><h2>Gửi yêu cầu bảo hành</h2><p>Mô tả vấn đề để bộ phận kỹ thuật tiếp nhận.</p><form id="rma" class="stack"><label>Loại yêu cầu<select name="kind"><option value="rma">Bảo hành</option><option value="repair">Sửa chữa ngoài bảo hành</option></select></label><label>Serial / IMEI<input name="serial" required placeholder="Nhập mã Serial hoặc IMEI"></label><label>Mô tả sự cố<textarea name="problem" required placeholder="Mô tả tình trạng thiết bị..."></textarea></label><button>Gửi yêu cầu <span>→</span></button></form><div class="support-note">◇ &nbsp; Yêu cầu được lưu để bộ phận kỹ thuật theo dõi.</div></section></div><section class="panel rma-panel"><div class="panel-title-row"><div><span class="section-kicker">THEO DÕI HỖ TRỢ</span><h2>Yêu cầu RMA <span class="results-count">${rmas.length}</span></h2></div></div>${rmas.map(r=>`<div class="rma-row"><span class="warranty-icon">◇</span><div><strong>${h(r.id)} · ${h(r.serial)}</strong><small>${h(r.problem)}</small></div><span class="rma-status">${h(r.status)}</span>${isCustomer?'':`<button class="secondary" data-rma="${h(r.id)}">Cập nhật</button>`}</div>`).join('')||'<div class="small-empty"><span>◇</span><p>Chưa có yêu cầu hỗ trợ.</p></div>'}</section>`
}
