document.addEventListener('input',e=>{const configs={'inventory-filter':['[data-stock-row]','inventory-empty'],'warranty-filter':['[data-warranty-row]','warranty-empty'],'report-filter':['[data-report-row]','report-empty']};const config=configs[e.target.id];if(!config)return;const query=e.target.value.trim().toLocaleLowerCase('vi');let count=0;document.querySelectorAll(config[0]).forEach(row=>{const visible=row.dataset.search.includes(query);row.hidden=!visible;if(visible)count++});const empty=document.getElementById(config[1]);if(empty)empty.hidden=count>0||!document.querySelector(config[0])});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const list=tab.closest('[role="tablist"]');if(!list)return;const tabs=[...list.querySelectorAll('[role="tab"]')];const current=tabs.indexOf(tab);let next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(current+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[next].click();tabs[next].focus()});

document.addEventListener('keydown',e=>{if((e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey)||((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k')){const target=e.target;if(target instanceof HTMLElement&&(target.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(target.tagName)))return;if(dialog.open)return;e.preventDefault();document.querySelector('#header-search').click()}});
